const caseRow = $input.first().json;
const caseId = Array.isArray(caseRow) ? caseRow[0]?.id : caseRow?.id;
const prev = $('Extract Client ID').first().json;
return [{ json: { ...prev, case_id: caseId } }];

const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const d = $('Parse Deepseek Response').first().json;
const fields = $('Set Fields').first().json;
const hasScore = d.completeness_score !== null && d.completeness_score !== undefined;
const score = hasScore ? d.completeness_score : '—';
const basis = d.score_basis ? d.score_basis : (hasScore ? '' : 'no checklist, or no readable answer');
const label = d.completeness_label ?? 'Unknown';
const present = (d.catalogue_present ?? []).map(x => `<li style='padding:6px 0;border-bottom:1px solid #f0ede6;'><span style='color:#166534'>✅</span> ${esc(x)}</li>`).join('');
const missing = (d.catalogue_missing ?? []).map(x => `<li style='padding:6px 0;border-bottom:1px solid #f0ede6;'><span style='color:#991b1b'>❌</span> ${esc(x)}</li>`).join('');
const optional = (d.offcatalogue ?? []).map(x => `<li style='padding:6px 0;border-bottom:1px solid #f0ede6;'><span style='color:#92400e'>⚠️</span> ${esc(x)}</li>`).join('');
const scoreColor = !hasScore ? '#6b7280' : score >= 75 ? '#166534' : score >= 40 ? '#92400e' : '#991b1b';
const labelBg = label === 'Complete' ? '#dcfce7' : label === 'Mostly Complete' ? '#fef9c3' : label === 'Incomplete' ? '#ffedd5' : '#fee2e2';
const labelColor = label === 'Complete' ? '#166534' : label === 'Mostly Complete' ? '#92400e' : label === 'Incomplete' ? '#9a3412' : '#991b1b';

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#8a7a65;font-family:Georgia,serif;">
<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:32px 16px;">
