<p style="margin:0;font-size:42px;font-weight:bold;color:${scoreColor};font-family:Arial,sans-serif;">${score}</p>
        <p style="margin:2px 0 0;font-size:11px;color:#6b7280;">${esc(basis)}</p>
<p style="margin:0;font-size:12px;color:#6b7280;">out of 100</p>
