${d.ai_notes ? `<div style="background:#fef9c3;border-left:4px solid #C9A84C;padding:12px 16px;margin:16px 0;border-radius:0 6px 6px 0;"><strong style="color:#92400e;">⚠️ Notes:</strong> <span style="color:#444;">${esc(d.ai_notes)}</span></div>` : ''}
