const match = list.find(p => (p.specializations || []).includes(caseType));
const chosen = match || list[0];
if (!chosen) throw new Error('No active paralegal found');

const prev = $('Extract Client ID').first().json;
return [{ json: { ...prev, paralegal_id: chosen.id, paralegal_name: chosen.full_name } }];

// Entry gate. Nothing downstream runs until this passes - including the paid model call.
const MAX_FIELD = 5000;
const MAX_BODY  = 100000;
const ALLOWED_CASE = ['Family Visa','Employment-Based Green Card','Asylum','Naturalization','Other'];

const input = $input.first().json;
const body  = (input && typeof input === 'object') ? input.body : undefined;

const reasons = [];  // anything here rejects the request
const notes   = [];  // coercions we accepted, recorded for the humans downstream

let bodySize = -1;
try { bodySize = JSON.stringify(body === undefined ? null : body).length; } catch (e) { bodySize = -1; }
if (bodySize < 0) reasons.push('request body is not serialisable JSON');
else if (bodySize > MAX_BODY) reasons.push('request body is ' + bodySize + ' bytes, over the ' + MAX_BODY + ' byte limit');

const clean = (v) => {
  if (typeof v === 'number' || typeof v === 'boolean') v = String(v);
  if (typeof v !== 'string') return '';
  let s = v
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F]/g, '')  // control chars, keeping \n and \t
    .replace(/[\u200B-\u200D\u2060\uFEFF]/g, '')                                // zero-width
    .replace(/[\u202A-\u202E\u2066-\u2069]/g, '')                                // bidi overrides
    .trim();
  if (s.length > MAX_FIELD) { s = s.slice(0, MAX_FIELD); notes.push('a field was truncated to ' + MAX_FIELD + ' characters'); }
  return s;
};

const data   = (body && typeof body === 'object') ? body.data : undefined;
const fields = (data && Array.isArray(data.fields)) ? data.fields : null;
if (!fields) reasons.push('data.fields is missing or is not an array');

const field = (label) => fields ? fields.find(f => f && typeof f === 'object' && f.label === label) : undefined;
const value = (label) => { const f = field(label); return f ? f.value : undefined; };

const caseTypeRaw = (() => {
  const f = field('Case type');
  if (!f) return '';
  const v = Array.isArray(f.value) ? f.value[0] : f.value;
  if (Array.isArray(f.options)) {
    const o = f.options.find(x => x && x.id === v);
    if (o && typeof o.text === 'string') return o.text;
  }
  return typeof v === 'string' ? v : '';
})();

const full_name            = clean(value('Full name'));
const email                = clean(value('Email address')).toLowerCase();
const phone                = clean(value('Phone number'));
const document_description = clean(value('Document description'));
const country_of_origin    = clean(value('Country of origin'));

const caseClean = clean(caseTypeRaw);
let case_type = 'Other';
if (ALLOWED_CASE.indexOf(caseClean) !== -1) case_type = caseClean;
else if (caseClean) notes.push('case type ' + JSON.stringify(caseClean) + ' is outside the accepted set and was recorded as Other');
else notes.push('no case type supplied, recorded as Other');

if (!document_description) notes.push('no document description supplied, the review will have nothing to assess');

// Idempotency key: without one, a redelivery cannot be told apart from a new intake.
const source_event_id = clean(
  (data && (data.submissionId || data.responseId)) ||
  (body && body.eventId) || ''
);
if (!source_event_id) reasons.push('no idempotency key (data.submissionId or eventId) on the request');

// Shared secret. The webhook is public: anyone with the URL can drive a paid model call and
// two emails, and there is no rate limiting in front of it. A secret Tally sends as a hidden
// field costs nothing and rejects an unauthorised request in ~70 ms, before the model.
//
// Deliberately inert until configured. If HVL_INTAKE_SECRET is unset the check is skipped and
// says so in the notes, because shipping a closed gate before Tally is sending the field would
// have refused every real intake. **An unset secret is not protection** - the notes record
// which of the two states a run was in, so "we turned it on" is checkable rather than assumed.
const expectedSecret = String($env.HVL_INTAKE_SECRET || '');
if (expectedSecret) {
  const sent = clean(value('Intake secret')) || clean(body && body.intakeSecret);
  if (sent !== expectedSecret) {
    reasons.push('intake secret missing or wrong');
  }
} else {
  notes.push('HVL_INTAKE_SECRET is not set, so the shared-secret check did not run');
}

if (!full_name) reasons.push('full name is empty');

const emailOk = email.length > 0 && email.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
if (!emailOk) reasons.push('email ' + JSON.stringify(email) + ' is not a deliverable address');

return [{ json: {
  guard_ok: reasons.length === 0,
  guard_reasons: reasons,
  guard_notes: notes,
  source_event_id: source_event_id,
  full_name: full_name,
  email: email,
  phone: phone,
  case_type: case_type,
  document_description: document_description,
  country_of_origin: country_of_origin,
  received_at: new Date().toISOString(),
  body_bytes: bodySize
} }];

// A failure that is someone else's ceiling is not a defect of ours. The status vocabulary
// separates them: blocked = an external limit, error = our fault.
const e = $json.execution || {};
const msg = String((e.error && e.error.message) || 'unknown');
const node = e.lastNodeExecuted || null;
const external = /rate.?limit|429|quota|too many requests|daily limit|insufficient balance|payment required|402|503|502|504|timeout|ETIMEDOUT|ECONNRESET/i;
return [{ json: {
  n8n_execution_id: String(e.id == null ? '' : e.id),
  status: external.test(msg) ? 'blocked' : 'error',
  stage: 'failed',
  error_node: node,
  error_message: msg.slice(0, 1000),
  finished_at: new Date().toISOString()
} }];
